export type AnnotationAnchorState = "anchored" | "drifted";

export type AnnotationDto = {
	id: string,
	document: string,
	blockId: string,
	start: number,
	end: number,
	quote: string,
	kind: AnnotationKind,
	body: string | null,
	createdAt: string,
	updatedAt: string,
	anchorState: AnnotationAnchorState,
};

export type AnnotationKind = "highlight" | "comment";

/**
 *  What the author sees (SPEC 9.8). Values extend the same schema; nothing
 *  here may become a second authority for behaviour.
 */
export type AppearanceConfig = {
	/**
	 *  One of the themes the generator emitted; validated on apply, not on
	 *  load, because the theme list is generated, not a hand copy.
	 */
	theme: string,
	typography: TypographyConfig,
	/**
	 *  Named snapshots of complete typography values. The active value above
	 *  remains authoritative; a preset changes nothing until the author applies it.
	 */
	typography_presets?: TypographyPreset[],
	/**  The manuscript sheet's edge: none / hairline / paper. */
	paper?: PaperMode,
	/**  What panels are made of. Solid by default: it costs nothing to draw. */
	panel_material?: PanelMaterial,
	/**
	 *  The author's chosen code colouring, or None to follow the interface
	 *  theme. None is not a missing value: it is "keep matching the theme",
	 *  and it must survive a theme change, which a resolved default cannot.
	 */
	code_theme?: string | null,
	/**
	 *  The night lamp, so the light has a source instead of the glyphs
	 *  appearing to emit it themselves.
	 */
	night_lamp?: NightLamp,
	/**  How wide a panel opens. */
	panel_width?: PanelWidth,
	/**  How wide the document rail sits. */
	rail_width?: RailWidth,
	/**  Which side panels open from. Left by default. */
	panel_side?: PanelSide,
	/**
	 *  Whether panels animate open. Off shortens the motion to 1ms rather than
	 *  taking a separate, untravelled code path.
	 */
	panel_animation?: boolean,
	/**
	 *  The writing-entry icon, by content digest. The asset named by this
	 *  digest lives in the application data assets directory.
	 */
	icon_digest?: string | null,
};

/**
 *  The click. Re-compiles from the same inputs; INV-14 refuses a drifted
 *  digest before any Run exists. One command, two shapes: the first
 *  authorization mints the runs; a retry's authorization names queued runs.
 */
export type AuthorizeDispatchRequest = {
	rootId: string,
	taskId: string,
	path: string,
	blockIds: string[],
	materialPaths: string[],
	prompt: string,
	clickedDigest: string,
	newAgents: string[],
	retryRunIds: string[],
	/**
	 *  The ticket's picked agent, for the contract tier. Retry mints no new
	 *  agents, so this cannot be derived from `new_agents`.
	 */
	agentId: string,
	carry: CarryMode,
};

/**
 *  What the Source Backup attempt produced, in the author's terms. `Failed`
 *  is a degradation the interface reports and offers to retry — the Root
 *  stays editable (Q23).
 */
export type BackupStatus = { kind: "taken"; value: {
	files: number,
} } | { kind: "alreadyPresent" } | { kind: "nothingToCopy" } | { kind: "failed"; value: {
	reason: string,
} };

export type BlockDto = {
	id: string,
	text: string,
	/**
	 *  Display-width equivalents: CJK and full-width punctuation count two.
	 *  Wrapping follows display width, not code point count, and in CJK prose
	 *  the two differ by nearly a factor of two.
	 */
	widthUnits: number,
	/**  Line breaks the author typed. A block occupies at least this many plus one. */
	hardLines: number,
	/**  The widest single line: a narrow block does not wrap just because it is long. */
	maxLineUnits: number,
	/**  A fence keeps the author's lines instead of wrapping. */
	isFence: boolean,
};

export type BuiltinTypographyPreset = {
	id: string,
	typography: TypographyConfig,
};

/**
 *  The carry tier the author picks on the ticket (KL9's context tiers):
 *  what rides besides the scope and the prompt. Materials always travel
 *  separately and are never part of a tier.
 */
export type CarryMode = 
/**
 *  The verdict stream; a round with no history falls back to the whole
 *  text, or the agent has nothing to stand on (KL9: never trade output
 *  quality for tokens).
 */
"diff" | 
/**  The verdict stream plus the whole manuscript, every round. */
"full" | 
/**  Neither verdicts nor manuscript — scope and prompt only. */
"none";

export type CollectOutcomeDto = 
/**  No result yet; nothing moved. */
{ kind: "waiting" } | { kind: "completed"; value: {
	proposals: number,
	memos: number,
	drafts: number,
} } | { kind: "failed"; value: {
	code: string,
	detail: string,
} };

/**
 *  The complete effective Config. This is the only shape Settings and
 *  Connections pages ever read.
 */
export type Config = {
	version: number,
	kara: KaraConfig,
	appearance?: AppearanceConfig,
	harness_connections?: HarnessConnection[],
	/**  The author's Agents: a name, a channel, an optional persona. */
	agents?: AgentProfile[],
};

/**
 *  The effective Config plus anything the author must be told about the load
 *  or write itself.
 */
export type ConfigSnapshot = {
	config: Config,
	/**
	 *  A divergent interrupted write preserved before this load or save
	 *  proceeded (SPEC 11: evidence, not silence).
	 */
	recoveryEvidence: string | null,
};

export type DispatchPreviewDto = {
	manifest: ManifestEntry[],
	digest: string,
	requestMd: string,
};

export type DisplayProfile = {
	monitor: string | null,
	physicalWidth: number,
	physicalHeight: number,
	scaleFactor: number | null,
	refreshHz: number | null,
	refreshMeasured: boolean,
	frameBudgetMs: number | null,
	hairlineCssPx: number | null,
};

export type DocumentPageDto = {
	documents: DocumentRow[],
	total: number,
	next: string | null,
};

/**  What a Markdown file is to the work. */
export type DocumentRole = 
/**  A standalone work opened on its own (single-file Root). */
"document" | 
/**  Part of a Project's manuscript sequence. */
"chapter" | 
/**
 *  Reference material: enters the Context picker, never the manuscript
 *  order.
 */
"material";

/**  A document row as the project database knows it. */
export type DocumentRow = {
	id: Id,
	/**  Portable identity inside the Root: the relative path, `/`-joined. */
	path: string,
	role: DocumentRole,
	digest: string | null,
	/**  The confirmed revision id and lineage paired with the digest. */
	currentHead: string | null,
	headBlockIds: string | null,
};

export type DroppedImportKind = "manuscript" | "material";

/**  The editor's settled input, as it crosses the bridge. */
export type EditorActionDto = {
	base: string,
	changes: EditorChangeDto[],
};

export type EditorChangeDto = { kind: "replace"; value: {
	blocks: string[],
	text: string | null,
} } | { kind: "insert"; value: {
	before: string | null,
	texts: string[],
} };

/**
 *  The single authority for error kinds. `verify:docs-current` enumerates this
 *  type and fails when a document explains fewer codes than it declares.
 */
export type ErrorCode = "permission-denied" | "illegal-name" | "occupied" | "outside-root" | "source-backup" | "not-a-directory" | "unsupported-format" | "state-unavailable" | "io" | 
/**
 *  The manuscript moved underneath a Proposal.
 * 
 *  The Agent froze the text it was reading; the author has since changed
 *  it. Applying the proposal anyway would overwrite words the Agent never
 *  saw, and discarding it silently would throw away the Agent's work —
 *  neither is ours to decide, so this reaches the author as its own fact
 *  rather than as a generic I/O failure.
 */
"stale-proposal";

